use ruff_diagnostics::{Diagnostic, Edit, Fix, FixAvailability, Violation};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_trivia::{CommentRanges, SimpleTokenKind, SimpleTokenizer};
use ruff_source_file::{find_newline, LineEnding, LineRanges};
use ruff_text_size::{TextRange, TextSize};

use crate::settings::LinterSettings;
use crate::Locator;

use super::super::detection::comment_contains_code;

/// ## What it does
/// Checks for commented-out Python code.
///
/// ## Why is this bad?
/// Commented-out code is dead code, and is often included inadvertently.
/// It should be removed.
///
/// ## Known problems
/// Prone to false positives when checking comments that resemble Python code,
/// but are not actually Python code ([#4845]).
///
/// ## Example
/// ```python
/// # print("Hello, world!")
/// ```
///
/// ## Options
/// - `lint.task-tags`
///
/// [#4845]: https://github.com/astral-sh/ruff/issues/4845
#[derive(ViolationMetadata)]
pub(crate) struct CommentedOutCode;

impl Violation for CommentedOutCode {
    const FIX_AVAILABILITY: FixAvailability = FixAvailability::None;

    #[derive_message_formats]
    fn message(&self) -> String {
        "Found commented-out code".to_string()
    }

    fn fix_title(&self) -> Option<String> {
        Some("Remove commented-out code".to_string())
    }
}

/// ERA001
pub(crate) fn commented_out_code(
    diagnostics: &mut Vec<Diagnostic>,
    locator: &Locator,
    comment_ranges: &CommentRanges,
    settings: &LinterSettings,
) {
    let mut comments = comment_ranges.into_iter().peekable();
    // Iterate over all comments in the document.
    while let Some(range) = comments.next() {
        let line = locator.line_str(range.start());

        if is_script_tag_start(line) {
            if skip_script_comments(range, &mut comments, locator) {
                continue;
            }
        }

        // Verify that the comment is on its own line, and that it contains code.
        if is_own_line_comment(line) && comment_contains_code(line, &settings.task_tags[..]) {
            let mut diagnostic = Diagnostic::new(CommentedOutCode, range);
            diagnostic.set_fix(Fix::display_only_edit(Edit::range_deletion(
                locator.full_lines_range(range),
            )));
            diagnostics.push(diagnostic);
        }
    }
}

/// Parses the rest of a [PEP 723](https://peps.python.org/pep-0723/)
/// script comment and moves `comments` past the script comment's end unless
/// the script comment is invalid.
///
/// Returns `true` if it is a valid script comment.
fn skip_script_comments<I>(
    script_start: TextRange,
    comments: &mut std::iter::Peekable<I>,
    locator: &Locator,
) -> bool
where
    I: Iterator<Item = TextRange>,
{
    let contents = locator.contents();
    let source_len = locator.text_len();
    let index = locator.to_index();
    let source_code = locator.to_source_code();
    let opening_offset = locator.floor_char_boundary(script_start.end());

    let line_end = if opening_offset >= source_len {
        source_len
    } else {
        let opening_tail = source_code.after(opening_offset);
        match find_newline(opening_tail) {
            Some((newline_at, LineEnding::Lf)) => {
                opening_offset + TextSize::try_from(newline_at).unwrap() + TextSize::new(1)
            }
            Some((newline_at, LineEnding::Cr)) => {
                opening_offset + TextSize::try_from(newline_at).unwrap() + TextSize::new(1)
            }
            Some((newline_at, LineEnding::CrLf)) => {
                opening_offset + TextSize::try_from(newline_at).unwrap() + TextSize::new(2)
            }
            None => source_len,
        }
    };

    if line_end >= source_len {
        return false;
    }

    let mut row = index.line_index(line_end);
    let mut end_offset = None;
    let line_count = index.line_count();

    while row.to_zero_indexed() < line_count {
        let line_start = index.line_start(row, contents);
        let line_stop = index.line_end(row, contents);
        if line_start >= source_len {
            break;
        }

        let full_range = TextRange::new(line_start, line_stop.min(source_len));
        let full_text = source_code.slice(full_range);
        let without_newline = match find_newline(full_text) {
            Some((newline_at, LineEnding::Lf)) => &full_text[..newline_at],
            Some((newline_at, LineEnding::Cr)) => &full_text[..newline_at],
            Some((newline_at, LineEnding::CrLf)) => &full_text[..newline_at],
            None => full_text,
        };

        if without_newline.is_empty() {
            break;
        }

        let first_token = SimpleTokenizer::starts_at(TextSize::default(), without_newline).next();
        let content = match first_token {
            Some(token) if token.kind() == SimpleTokenKind::Comment => {
                match script_line_content(without_newline) {
                    Some(payload) => payload,
                    None => break,
                }
            }
            Some(_) => break,
            None => break,
        };

        let terminator = content == "///";
        if !terminator {
            row = row.saturating_add(1);
            continue;
        }

        let next_row = row.saturating_add(1);
        if next_row.to_zero_indexed() >= line_count {
            end_offset = Some(line_stop);
            break;
        }

        let next_start = index.line_start(next_row, contents);
        if next_start >= source_len {
            end_offset = Some(line_stop);
            break;
        }

        let next_stop = index.line_end(next_row, contents);
        let next_range = TextRange::new(next_start, next_stop.min(source_len));
        let next_full_text = source_code.slice(next_range);
        let next_without_newline = match find_newline(next_full_text) {
            Some((newline_at, LineEnding::Lf)) => &next_full_text[..newline_at],
            Some((newline_at, LineEnding::Cr)) => &next_full_text[..newline_at],
            Some((newline_at, LineEnding::CrLf)) => &next_full_text[..newline_at],
            None => next_full_text,
        };

        let next_token = SimpleTokenizer::starts_at(TextSize::default(), next_without_newline).next();
        let next_is_embedded_content_line = match next_token {
            Some(token) if token.kind() == SimpleTokenKind::Comment => {
                let comment_text = &next_without_newline[token.range];
                let after_hash = comment_text.strip_prefix('#').unwrap_or("");
                if after_hash.is_empty() {
                    true
                } else if after_hash.starts_with(' ') {
                    true
                } else {
                    false
                }
            }
            Some(_) => is_valid_script_line(next_without_newline),
            None => false,
        };

        if next_is_embedded_content_line {
            row = next_row.saturating_add(1);
            continue;
        }

        end_offset = Some(line_stop);
        break;
    }

    let Some(end_offset) = end_offset else {
        return false;
    };

    while let Some(comment) = comments.peek().copied() {
        match comment.start().cmp(&end_offset) {
            std::cmp::Ordering::Less => {
                comments.next();
            }
            std::cmp::Ordering::Equal | std::cmp::Ordering::Greater => break,
        }
    }

    true
}

fn script_line_content(line: &str) -> Option<&str> {
    let Some(rest) = line.strip_prefix('#') else {
        // Not a comment
        return None;
    };

    // An empty line
    if rest.is_empty() {
        return Some("");
    }

    // > If there are characters after the # then the first character MUST be a space.
    rest.strip_prefix(' ')
}

fn is_valid_script_line(line: &str) -> bool {
    script_line_content(line).is_some()
}

/// Returns `true` if line contains an own-line comment.
fn is_own_line_comment(line: &str) -> bool {
    for char in line.chars() {
        if char == '#' {
            return true;
        }
        if !char.is_whitespace() {
            return false;
        }
    }
    unreachable!("Comment should contain '#' character")
}

/// Returns `true` if the line appears to start a script tag.
///
/// See: <https://peps.python.org/pep-0723/>
fn is_script_tag_start(line: &str) -> bool {
    line == "# /// script"
}

#[cfg(test)]
mod tests {
    use ruff_python_parser::parse_module;
    use ruff_python_trivia::CommentRanges;
    use ruff_source_file::LineRanges;
    use ruff_text_size::TextSize;

    use crate::rules::eradicate::rules::commented_out_code::skip_script_comments;
    use crate::Locator;

    #[test]
    fn script_comment() {
        let code = r#"
# /// script
# requires-python = ">=3.11"
# dependencies = [
#   "requests<3",
#   "rich",
# ]
# ///

a = 10 # abc
        "#;

        let parsed = parse_module(code).unwrap();
        let locator = Locator::new(code);

        let comments = CommentRanges::from(parsed.tokens());
        let mut comments = comments.into_iter().peekable();

        let script_start = code.find("# /// script").unwrap();
        let script_start_range = locator.full_line_range(TextSize::try_from(script_start).unwrap());

        let valid = skip_script_comments(script_start_range, &mut comments, &Locator::new(code));

        assert!(valid);

        let next_comment = comments.next();

        assert!(next_comment.is_some());
        assert_eq!(&code[next_comment.unwrap()], "# abc");
    }

    #[test]
    fn script_comment_end_precedence() {
        let code = r#"
# /// script
# [tool.uv]
# extra-index-url = ["https://pypi.org/simple", """\
# https://example.com/
# ///
# """
# ]
# ///

a = 10 # abc
        "#;

        let parsed = parse_module(code).unwrap();
        let locator = Locator::new(code);

        let comments = CommentRanges::from(parsed.tokens());
        let mut comments = comments.into_iter().peekable();

        let script_start = code.find("# /// script").unwrap();
        let script_start_range = locator.full_line_range(TextSize::try_from(script_start).unwrap());

        let valid = skip_script_comments(script_start_range, &mut comments, &Locator::new(code));

        assert!(valid);

        let next_comment = comments.next();

        assert!(next_comment.is_some());
        assert_eq!(&code[next_comment.unwrap()], "# abc");
    }
}

